{
  "name": "builder_simple_rank_pairs_v2",
  "intuition": "Build pairwise preferences by ranking candidates within each instance using the objective (lower is better), then emitting a deterministic subset of comparisons: always best-vs-worst for coverage plus as many adjacent-rank comparisons as allowed by max_pairs_per_instance to provide a stable learning signal without quadratic pairing.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
