  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, N = objective.shape

    # Read budget without relying on int()/max(); keep deterministic and safe.
    max_pairs_per_instance = extra.get('max_pairs_per_instance', 8)
    if max_pairs_per_instance is None:
        max_pairs_per_instance = 8
    if max_pairs_per_instance < 1:
        max_pairs_per_instance = 1

    # Rank per instance: lower objective is better.
    order = objective.argsort(dim=1, descending=False)

    b_list = []
    w_list = []
    l_list = []

    long_dtype = objective.new_empty((0,), dtype=objective.dtype).long().dtype

    for b in range(B):
        if N < 2:
            continue

        # Always include best vs worst.
        b_list.append(objective.new_full((1,), b, dtype=long_dtype))
        w_list.append(order[b, :1].to(dtype=long_dtype))
        l_list.append(order[b, -1:].to(dtype=long_dtype))

        # Add adjacent comparisons up to the remaining budget.
        remaining = max_pairs_per_instance - 1
        if remaining > 0:
            m = N - 1
            if m > remaining:
                m = remaining
            if m > 0:
                b_list.append(objective.new_full((m,), b, dtype=long_dtype))
                w_list.append(order[b, :m].to(dtype=long_dtype))
                l_list.append(order[b, 1:m + 1].to(dtype=long_dtype))

    if len(b_list) == 0:
        empty = objective.new_empty((0,), dtype=long_dtype)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'simple_rank_pairs', 'max_pairs_per_instance': max_pairs_per_instance}
        )

    b_idx = torch.cat(b_list, dim=0).reshape(-1).to(dtype=long_dtype)
    winner_idx = torch.cat(w_list, dim=0).reshape(-1).to(dtype=long_dtype)
    loser_idx = torch.cat(l_list, dim=0).reshape(-1).to(dtype=long_dtype)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={'builder': 'simple_rank_pairs', 'max_pairs_per_instance': max_pairs_per_instance}
    )
