  "name": "builder_rank_strata_noint",
  "intuition": "Build a small, deterministic set of informative pairwise preferences per instance by ranking candidates by objective (lower is better) and comparing the best choice against a near-best, a mid-ranked, and a worst-ranked option (plus an optional adjacent mid pair), capping the number of pairs while preserving full batch coverage.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, N = objective.shape

    # Avoid calling int(...) (some runtimes restrict builtins).
    pairs_per_instance = extra.get('pairs_per_instance', 4)
    if pairs_per_instance is None:
        pairs_per_instance = 4
    # Coerce to a safe positive integer-ish value.
    try:
        pairs_per_instance = pairs_per_instance + 0
    except Exception:
        pairs_per_instance = 4
    if pairs_per_instance < 1:
        pairs_per_instance = 1

    # Indices sorted by objective ascending: rank 0 is best.
    sorted_idx = objective.argsort(dim=1, stable=True)

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        if N <= 1:
            continue
        s = sorted_idx[b]

        cand = []
        # best vs near-best
        if N >= 2:
            cand.append((0, 1))
        # best vs mid
        if N >= 3:
            cand.append((0, N // 2))
        # best vs tail
        if N >= 4:
            cand.append((0, N - 1))
        # adjacent around mid (local ordering)
        if N >= 4:
            mid = N // 2
            if mid + 1 < N:
                cand.append((mid, mid + 1))

        # Deduplicate while preserving order.
        seen = set()
        cand2 = []
        for wr, lr in cand:
            if wr == lr:
                continue
            key = (wr, lr)
            if key in seen:
                continue
            seen.add(key)
            cand2.append((wr, lr))

        if len(cand2) > pairs_per_instance:
            cand2 = cand2[:pairs_per_instance]
        if len(cand2) == 0:
            cand2 = [(0, N - 1)]

        for wr, lr in cand2:
            w = s[wr]
            l = s[lr]
            b_list.append(b)
            w_list.append(w)
            l_list.append(l)

    b_idx = objective.new_tensor(b_list, dtype=torch.long).view(-1)
    winner_idx = objective.new_tensor(w_list, dtype=torch.long).view(-1)
    loser_idx = objective.new_tensor(l_list, dtype=torch.long).view(-1)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'rank_strata_noint',
            'pairs_per_instance': pairs_per_instance,
            'pairing': 'rank_stratified'
        }
    )"
}

