        ref = batch.get('log_prob_l', batch.get('logp_l', batch.get('rejected_log_prob', None)))
        lpw = ref * 0.0 if ref is not None else ops.zeros(())

    if 'log_prob_l' in batch:
        lpl = batch['log_prob_l']
    elif 'logp_l' in batch:
        lpl = batch['logp_l']
    elif 'rejected_log_prob' in batch:
